// Keep only the attachments LedgerLens accepts (spec §7 whitelist:
// PDF/PNG/JPG, 10 MB). Filtering here saves a round trip and keeps the
// mailbox's junk out of the ledger.
const MAX_BYTES = 10 * 1024 * 1024;
const ALLOWED = ['application/pdf', 'image/png', 'image/jpeg'];
const out = [];

for (const item of $input.all()) {
  const binaries = item.binary ?? {};
  for (const key of Object.keys(binaries)) {
    const file = binaries[key];
    const type = (file.mimeType || '').toLowerCase();
    const size = Number(file.fileSize ?? 0);
    if (!ALLOWED.includes(type)) continue;
    if (size > MAX_BYTES) continue;
    out.push({
      json: {
        filename: file.fileName ?? 'document',
        mimeType: type,
        from: item.json.from ?? null,
        subject: item.json.subject ?? null,
      },
      binary: { data: file },
    });
  }
}

return out;

